#include "merge_sort.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

static int failures = 0;
static int tests_run = 0;

/* Overflow-safe comparator (don't use a - b with INT_MIN/INT_MAX!) */
static int cmp_int(const void *x, const void *y) {
    int a = *(const int *)x, b = *(const int *)y;
    return (a > b) - (a < b);
}

/* Sort a copy with merge_sort and another with qsort, then compare. */
static void check(const char *name, const int *input, size_t n) {
    tests_run++;
    int *got  = malloc((n ? n : 1) * sizeof *got);
    int *want = malloc((n ? n : 1) * sizeof *want);
    if (n) { memcpy(got, input, n * sizeof *got);
             memcpy(want, input, n * sizeof *want); }

    merge_sort(got, n);
    qsort(want, n, sizeof *want, cmp_int);

    if (n && memcmp(got, want, n * sizeof *got) != 0) {
        printf("FAIL: %s\n", name);
        failures++;
    } else {
        printf("ok:   %s\n", name);
    }
    free(got);
    free(want);
}

#define CHECK_ARRAY(name, ...) do {                              \
    int arr_[] = { __VA_ARGS__ };                                \
    check(name, arr_, sizeof arr_ / sizeof arr_[0]);             \
} while (0)

static void test_edge_cases(void) {
    check("empty", NULL, 0);
    CHECK_ARRAY("single", 42);
    CHECK_ARRAY("two sorted", 1, 2);
    CHECK_ARRAY("two reversed", 2, 1);
    CHECK_ARRAY("already sorted", 1, 2, 3, 4, 5, 6);
    CHECK_ARRAY("reverse sorted", 6, 5, 4, 3, 2, 1);
    CHECK_ARRAY("all equal", 7, 7, 7, 7, 7);
    CHECK_ARRAY("duplicates", 3, 1, 3, 2, 1, 2, 3);
    CHECK_ARRAY("negatives", -5, 3, -1, 0, -10, 8);
    CHECK_ARRAY("int limits", INT_MAX, INT_MIN, 0, INT_MAX, INT_MIN);
    CHECK_ARRAY("odd length", 5, 2, 9, 1, 7);
}

static void test_random(void) {
    srand(12345); /* fixed seed so failures are reproducible */
    for (int trial = 0; trial < 1000; trial++) {
        size_t n = (size_t)(rand() % 200);
        int *a = malloc((n ? n : 1) * sizeof *a);
        for (size_t i = 0; i < n; i++) a[i] = rand() % 100 - 50;
        char name[64];
        snprintf(name, sizeof name, "random trial %d (n=%zu)", trial, n);

        /* quiet version: only print failures */
        int before = failures;
        int *got = malloc((n ? n : 1) * sizeof *got);
        if (n) memcpy(got, a, n * sizeof *a);
        merge_sort(got, n);
        qsort(a, n, sizeof *a, cmp_int);
        tests_run++;
        if (n && memcmp(got, a, n * sizeof *a) != 0) {
            printf("FAIL: %s\n", name);
            failures++;
        }
        (void)before;
        free(got);
        free(a);
    }
}

int main(void) {
    test_edge_cases();
    test_random();
    printf("\n%d tests run, %d failed\n", tests_run, failures);
    return failures ? 1 : 0;
}
